preview.previewHEarthWetSandGeometry:
export function previewHEarthWetSandGeometry(input) {
  const inputCheck =
    checkHEarthWetSandPreviewTranslationInput(input);

  if (!inputCheck.ok) {
    return buildRejectedResult({
      sourceObjectId:
        inputCheck.normalizedInput.sourceObjectId,
      requestId:
        inputCheck.normalizedInput.requestId,
      requestedPurpose:
        inputCheck.normalizedInput.requestedPurpose,
      issues:
        inputCheck.issues
    });
  }

  const packet001Result =
    resolveHEarthSourceObjectGeometryRequest({
      sourceObjectId:
        inputCheck.normalizedInput.sourceObjectId,
      requestedPurpose:
        inputCheck.normalizedInput.requestedPurpose,
      requestId:
        inputCheck.normalizedInput.requestId
    });

  return constructHEarthWetSandPreview({
    packet001Result,
    wetSandProfile:
      H_EARTH_3D_WET_SAND_NUMERIC_CONSTRUCTION_PROFILE
  });
}

packet002.validatePreviewResult:
function validatePreviewResult(previewResult) {
  const issues = [];

  if (!isPlainRecord(previewResult)) {
    issues.push({
      code: 'PREVIEW_RESULT_MISSING',
      message:
        'previewResult must be a plain-record object.',
      field: 'previewResult'
    });

    return Object.freeze({
      ok: false,
      issues: freezeIssues(issues),
      requestId: null,
      providerRequestId: null,
      resolutionReceiptId: null,
      sourceObjectIds: EMPTY_FROZEN_ARRAY,
      sourceZoneIds: EMPTY_FROZEN_ARRAY,
      latticeRegionIds: EMPTY_FROZEN_ARRAY
    });
  }

  const sourceObjectIds =
    derivePreviewSourceObjectIds(previewResult);

  const sourceZoneIds =
    derivePreviewSourceZoneIds(previewResult);

  const latticeRegionIds =
    derivePreviewLatticeRegionIds(previewResult);

  if (previewResult.ok !== true) {
    issues.push({
      code: 'PREVIEW_RESULT_NOT_LAWFUL',
      message:
        'previewResult must be lawful before Packet 002 transfer.',
      actual:
        previewResult.status ?? null
    });
  }

  if (
    previewResult.contractId !==
    EXPECTED_PREVIEW_CONTRACT_ID
  ) {
    issues.push({
      code: 'PREVIEW_RESULT_CONTRACT_ID_MISMATCH',
      message:
        'previewResult contractId does not match the controlling preview occurrence.',
      expected:
        EXPECTED_PREVIEW_CONTRACT_ID,
      actual:
        previewResult.contractId ?? null
    });
  }

  if (!isNonEmptyString(previewResult.requestId)) {
    issues.push({
      code: 'REQUEST_ID_MISSING',
      message:
        'previewResult.requestId is required.',
      field: 'requestId'
    });
  }

  if (!isNonEmptyString(previewResult.providerRequestId)) {
    issues.push({
      code: 'PROVIDER_REQUEST_ID_MISSING',
      message:
        'previewResult.providerRequestId is required.',
      field: 'providerRequestId'
    });
  }

  if (!isNonEmptyString(previewResult.resolutionReceiptId)) {
    issues.push({
      code: 'RESOLUTION_RECEIPT_ID_MISSING',
      message:
        'previewResult.resolutionReceiptId is required.',
      field: 'resolutionReceiptId'
    });
  }

  if (sourceObjectIds.length === 0) {
    issues.push({
      code: 'SOURCE_OBJECT_PROVENANCE_MISSING',
      message:
        'previewResult must preserve one or more sourceObjectIds.'
    });
  }

  if (sourceZoneIds.length === 0) {
    issues.push({
      code: 'SOURCE_ZONE_PROVENANCE_MISSING',
      message:
        'previewResult must preserve one or more sourceZoneIds.'
    });
  }

  if (latticeRegionIds.length === 0) {
    issues.push({
      code: 'LATTICE_REGION_PROVENANCE_MISSING',
      message:
        'previewResult must preserve one or more latticeRegionIds.'
    });
  }

  if (previewResult.admitted === true) {
    issues.push({
      code: 'PREVIEW_RESULT_ALREADY_ADMITTED',
      message:
        'previewResult must remain unadmitted at the preview boundary.'
    });
  }

  if (
    previewResult.geometryIndexEntryId !== undefined &&
    previewResult.geometryIndexEntryId !== null
  ) {
    issues.push({
      code: 'PREMATURE_GEOMETRY_INDEX_IDENTITY',
      message:
        'previewResult must not carry a geometryIndexEntryId.'
    });
  }

  if (
    previewResult.compositorNodeId !== undefined &&
    previewResult.compositorNodeId !== null
  ) {
    issues.push({
      code: 'PREMATURE_COMPOSITOR_IDENTITY',
      message:
        'previewResult must not carry a compositorNodeId.'
    });
  }

  if (
    previewResult.renderInstanceId !== undefined &&
    previewResult.renderInstanceId !== null
  ) {
    issues.push({
      code: 'PREMATURE_RENDER_INSTANCE_IDENTITY',
      message:
        'previewResult must not carry a renderInstanceId.'
    });
  }

  return Object.freeze({
    ok: issues.length === 0,
    issues: freezeIssues(issues),
    requestId:
      isNonEmptyString(previewResult.requestId)
        ? previewResult.requestId.trim()
        : null,
    providerRequestId:
      isNonEmptyString(previewResult.providerRequestId)
        ? previewResult.providerRequestId.trim()
        : null,
    resolutionReceiptId:
      isNonEmptyString(previewResult.resolutionReceiptId)
        ? previewResult.resolutionReceiptId.trim()
        : null,
    sourceObjectIds,
    sourceZoneIds,
    latticeRegionIds
  });
}

packet002.validateWestPrimitiveAdmission:
function validateWestPrimitiveAdmission(
  primitiveAdmission,
  previewValidation
) {
  const issues = [];

  if (!isPlainRecord(primitiveAdmission)) {
    issues.push({
      code: 'PRIMITIVE_ADMISSION_RESULT_MISSING',
      message:
        'Every West primitive admission must be a plain-record object.'
    });

    return Object.freeze({
      ok: false,
      issues: freezeIssues(issues),
      admittedPrimitive: null,
      admittedGeometry: null,
      sourceObjectIds: EMPTY_FROZEN_ARRAY,
      sourceZoneIds: EMPTY_FROZEN_ARRAY,
      latticeRegionIds: EMPTY_FROZEN_ARRAY
    });
  }

  const admittedPrimitive =
    primitiveAdmission.primitive;

  const admittedGeometry =
    primitiveAdmission.geometry;

  const primitiveOccurrenceLawful =
    primitiveAdmission.valid === true &&
    isHEarthAdmittedPrimitiveRecord(admittedPrimitive) &&
    isHEarthAdmittedGeometryRecord(admittedGeometry) &&
    admittedPrimitive.geometry === admittedGeometry &&
    admittedPrimitive.admissionId ===
      primitiveAdmission.admissionId &&
    admittedPrimitive.primitiveId ===
      admittedGeometry.sourceNeutralPrimitiveId &&
    admittedPrimitive.admissionAuthority === 'WEST' &&
    admittedPrimitive.admitted === true &&
    admittedPrimitive.aggregateFrameMember === false &&
    admittedPrimitive.recordType ===
      'H_EARTH_WEST_ADMITTED_PRIMITIVE_RECORD' &&
    admittedGeometry.recordType ===
      'H_EARTH_WEST_ADMITTED_GEOMETRY_RECORD' &&
    admittedGeometry.admitted === true &&
    admittedGeometry.admissionAuthority === 'WEST' &&
    admittedGeometry.geometryIndexExported === false &&
    admittedGeometry.compositorIntegrated === false &&
    admittedGeometry.rendererMaterialized === false;

  if (!primitiveOccurrenceLawful) {
    issues.push({
      code: 'PRIMITIVE_ADMISSION_REJECTED',
      message:
        'A West primitive admission occurrence is not lawful under the public geometry-kernel facade.'
    });
  }

  const metadata =
    derivePrimitiveMetadata(admittedPrimitive);

  const sourceObjectIds =
    canonicalUniqueStrings(
      metadata?.sourceObjectIds ?? [
        metadata?.sourceObjectId
      ]
    );

  const sourceZoneIds =
    canonicalUniqueStrings(
      metadata?.sourceZoneIds ?? [
        metadata?.zoneId
      ]
    );

  const latticeRegionIds =
    canonicalUniqueStrings(
      metadata?.latticeRegionIds
    );

  if (sourceObjectIds.length === 0) {
    issues.push({
      code: 'WEST_SOURCE_OBJECT_PROVENANCE_MISSING',
      message:
        'West admitted primitive metadata must preserve sourceObjectId.'
    });
  } else if (
    !arraysEqual(
      sourceObjectIds,
      previewValidation.sourceObjectIds
    )
  ) {
    issues.push({
      code: 'PRIMITIVE_PROVENANCE_MISMATCH',
      message:
        'West admitted primitive sourceObjectId does not match preview provenance.',
      expected:
        previewValidation.sourceObjectIds,
      actual:
        sourceObjectIds
    });
  }

  if (sourceZoneIds.length === 0) {
    issues.push({
      code: 'WEST_SOURCE_ZONE_PROVENANCE_MISSING',
      message:
        'West admitted primitive metadata must preserve zoneId.'
    });
  } else if (
    !arraysEqual(
      sourceZoneIds,
      previewValidation.sourceZoneIds
    )
  ) {
    issues.push({
      code: 'PRIMITIVE_PROVENANCE_MISMATCH',
      message:
        'West admitted primitive zoneId does not match preview provenance.',
      expected:
        previewValidation.sourceZoneIds,
      actual:
        sourceZoneIds
    });
  }

  return Object.freeze({
    ok: issues.length === 0,
    issues: freezeIssues(issues),
    admittedPrimitive,
    admittedGeometry,
    sourceObjectIds,
    sourceZoneIds,
    latticeRegionIds
  });
}

packet002.buildHEarthPostWestAdmittedGeometryTrans:
export function buildHEarthPostWestAdmittedGeometryTransfer(
  input
) {
  const inputEvaluation =
    evaluateHEarthPostWestAdmittedGeometryTransferInput(
      input
    );

  if (!inputEvaluation.ok) {
    return Object.freeze({
      ok: false,
      status:
        'H_EARTH_POST_WEST_ADMITTED_GEOMETRY_TRANSFER_REJECTED',
      contractId:
        H_EARTH_POST_WEST_ADMITTED_GEOMETRY_TRANSFER_CONTRACT_ID,
      issues:
        inputEvaluation.issues
    });
  }

  const {
    toleranceValidation,
    previewValidation,
    westBatchValidation
  } = inputEvaluation;

  const admittedPrimitivesSnapshot =
    snapshotForTransfer(
      westBatchValidation.admittedPrimitives,
      'admittedPrimitives'
    );

  if (!admittedPrimitivesSnapshot.ok) {
    return Object.freeze({
      ok: false,
      status:
        'H_EARTH_POST_WEST_ADMITTED_GEOMETRY_TRANSFER_REJECTED',
      contractId:
        H_EARTH_POST_WEST_ADMITTED_GEOMETRY_TRANSFER_CONTRACT_ID,
      issues: freezeIssues([
        admittedPrimitivesSnapshot.error
      ])
    });
  }

  const frameSnapshot =
    snapshotForTransfer(
      westBatchValidation.frame,
      'aggregateFrameAdmissionRecord'
    );

  if (!frameSnapshot.ok) {
    return Object.freeze({
      ok: false,
      status:
        'H_EARTH_POST_WEST_ADMITTED_GEOMETRY_TRANSFER_REJECTED',
      contractId:
        H_EARTH_POST_WEST_ADMITTED_GEOMETRY_TRANSFER_CONTRACT_ID,
      issues: freezeIssues([
        frameSnapshot.error
      ])
    });
  }

  const boundsSnapshot =
    snapshotForTransfer(
      westBatchValidation.bounds,
      'bounds'
    );

  if (!boundsSnapshot.ok) {
    return Object.freeze({
      ok: false,
      status:
        'H_EARTH_POST_WEST_ADMITTED_GEOMETRY_TRANSFER_REJECTED',
      contractId:
        H_EARTH_POST_WEST_ADMITTED_GEOMETRY_TRANSFER_CONTRACT_ID,
      issues: freezeIssues([
        boundsSnapshot.error
      ])
    });
  }

  const toleranceSnapshot =
    toleranceValidation.normalizedValue === null
      ? {
          ok: true,
          value: null
        }
      : snapshotForTransfer(
          toleranceValidation.normalizedValue,
          'toleranceContext'
        );

  if (!toleranceSnapshot.ok) {
    return Object.freeze({
      ok: false,
      status:
        'H_EARTH_POST_WEST_ADMITTED_GEOMETRY_TRANSFER_REJECTED',
      contractId:
        H_EARTH_POST_WEST_ADMITTED_GEOMETRY_TRANSFER_CONTRACT_ID,
      issues: freezeIssues([
        toleranceSnapshot.error
      ])
    });
  }

  return deepFreeze({
    ok: true,

    status:
      SUCCESS_STATUS,

    contractId:
      H_EARTH_POST_WEST_ADMITTED_GEOMETRY_TRANSFER_CONTRACT_ID,

    westContractId:
      H_EARTH_3D_GEOMETRY_KERNEL_WEST_CONTRACT_ID,

    requestId:
      previewValidation.requestId,

    providerRequestId:
      previewValidation.providerRequestId,

    resolutionReceiptId:
      previewValidation.resolutionReceiptId,

    sourceObjectIds:
      previewValidation.sourceObjectIds,

    sourceZoneIds:
      previewValidation.sourceZoneIds,

    latticeRegionIds:
      previewValidation.latticeRegionIds,

    admittedPrimitives:
      admittedPrimitivesSnapshot.value,

    aggregateFrameAdmissionRecord:
      frameSnapshot.value,

    bounds:
      boundsSnapshot.value,

    frameId:
      westBatchValidation.frameId,

    toleranceContext:
      toleranceSnapshot.value,

    geometryIndexAuthority: false,
    geometryIndexEntryId: null,

    compositorAuthority: false,
    compositorNodeId: null,

    rendererAuthority: false,
    renderInstanceCreated: false,
    renderInstanceId: null,

    provisional: true,
    downstreamContractFrozen: false,
    finalDownstreamShapeClaimed: false,

    issues:
      EMPTY_FROZEN_ARRAY
  });
}

frame.validatePacket002Transfer:
function validatePacket002Transfer(
  packet002Transfer,
  presentationMode
) {
  const issues = [];

  if (!isPlainRecord(packet002Transfer)) {
    return Object.freeze({
      ok: false,

      issues: freezeIssues([
        createBridgeIssue(
          'PACKET_002_TRANSFER_NOT_PLAIN_RECORD',
          'packet002Transfer must be a strict plain-record object.',
          {
            field:
              'packet002Transfer'
          }
        )
      ])
    });
  }

  if (!isDeeplyFrozen(packet002Transfer)) {
    issues.push(
      createBridgeIssue(
        'PACKET_002_TRANSFER_NOT_DEEPLY_FROZEN',
        'Packet 002 must preserve its producer-owned deeply frozen snapshot boundary before bridge consumption.',
        {
          field:
            'packet002Transfer'
        }
      )
    );
  }

  if (
    !Array.isArray(
      packet002Transfer.issues
    ) ||
    packet002Transfer.issues.length !== 0
  ) {
    issues.push(
      createBridgeIssue(
        'PACKET_002_TRANSFER_ISSUES_NOT_EMPTY',
        'A successful Packet 002 transfer must expose an empty issues array.',
        {
          field:
            'packet002Transfer.issues',

          expected:
            EMPTY_FROZEN_ARRAY,

          actual:
            Array.isArray(
              packet002Transfer.issues
            )
              ? packet002Transfer.issues
              : null
        }
      )
    );
  }

  if (
    packet002Transfer.contractId !==
    H_EARTH_POST_WEST_ADMITTED_GEOMETRY_TRANSFER_CONTRACT_ID
  ) {
    issues.push(
      createBridgeIssue(
        'PACKET_002_CONTRACT_MISMATCH',
        'Packet 002 contractId does not match the controlling transfer contract.',
        {
          field:
            'packet002Transfer.contractId',

          expected:
            H_EARTH_POST_WEST_ADMITTED_GEOMETRY_TRANSFER_CONTRACT_ID,

          actual:
            packet002Transfer.contractId ??
            null
        }
      )
    );
  }

  if (packet002Transfer.ok !== true) {
    issues.push(
      createBridgeIssue(
        'PACKET_002_NOT_SUCCESSFUL',
        'Packet 002 transfer must expose ok === true.',
        {
          field:
            'packet002Transfer.ok',

          expected:
            true,

          actual:
            packet002Transfer.ok ??
            null
        }
      )
    );
  }

  if (
    packet002Transfer.status !==
    EXPECTED_PACKET_002_STATUS
  ) {
    issues.push(
      createBridgeIssue(
        'PACKET_002_STATUS_MISMATCH',
        'Packet 002 status does not match the provisional post-West success state.',
        {
          field:
            'packet002Transfer.status',

          expected:
            EXPECTED_PACKET_002_STATUS,

          actual:
            packet002Transfer.status ??
            null
        }
      )
    );
  }

  if (
    packet002Transfer.provisional !==
    true
  ) {
    issues.push(
      createBridgeIssue(
        'PACKET_002_PROVISIONAL_FLAG_REQUIRED',
        'Packet 002 must remain provisional.',
        {
          field:
            'packet002Transfer.provisional',

          expected:
            true,

          actual:
            packet002Transfer.provisional ??
            null
        }
      )
    );
  }

  if (
    packet002Transfer.downstreamContractFrozen !==
    false
  ) {
    issues.push(
      createBridgeIssue(
        'PACKET_002_DOWNSTREAM_CONTRACT_FROZEN',
        'Packet 002 downstreamContractFrozen must remain false.',
        {
          field:
            'packet002Transfer.downstreamContractFrozen',

          expected:
            false,

          actual:
            packet002Transfer.downstreamContractFrozen ??
            null
        }
      )
    );
  }

  if (
    packet002Transfer.finalDownstreamShapeClaimed !==
    false
  ) {
    issues.push(
      createBridgeIssue(
        'PACKET_002_FINAL_DOWNSTREAM_SHAPE_CLAIMED',
        'Packet 002 finalDownstreamShapeClaimed must remain false.',
        {
          field:
            'packet002Transfer.finalDownstreamShapeClaimed',

          expected:
            false,

          actual:
            packet002Transfer.finalDownstreamShapeClaimed ??
            null
        }
      )
    );
  }

  if (
    packet002Transfer.westContractId !==
    H_EARTH_3D_GEOMETRY_KERNEL_WEST_CONTRACT_ID
  ) {
    issues.push(
      createBridgeIssue(
        'WEST_CONTRACT_MISMATCH',
        'Packet 002 westContractId does not match the controlling West contract.',
        {
          field:
            'packet002Transfer.westContractId',

          expected:
            H_EARTH_3D_GEOMETRY_KERNEL_WEST_CONTRACT_ID,

          actual:
            packet002Transfer.westContractId ??
            null
        }
      )
    );
  }

  for (
    const [field, expected]
    of [
      ['geometryIndexAuthority', false],
      ['compositorAuthority', false],
      ['rendererAuthority', false],
      ['renderInstanceCreated', false]
    ]
  ) {
    if (
      packet002Transfer[field] !==
      expected
    ) {
      issues.push(
        createBridgeIssue(
          'PREMATURE_AUTHORITY_FLAG_REJECTED',
          `${field} must remain false in Packet 002.`,
          {
            field:
              `packet002Transfer.${field}`,

            expected,

            actual:
              packet002Transfer[field] ??
              null
          }
        )
      );
    }
  }

  for (
    const field
    of PREMATURE_PACKET_002_IDENTITY_KEYS
  ) {
    if (
      packet002Transfer[field] !==
      null
    ) {
      issues.push(
        createBridgeIssue(
          'PREMATURE_DOWNSTREAM_IDENTITY_REJECTED',
          `${field} must remain null in Packet 002.`,
          {
            field:
              `packet002Transfer.${field}`,

            expected:
              null,

            actual:
              packet002Transfer[field] ??
              null
          }
        )
      );
    }
  }

  for (
    const field
    of [
      'requestId',
      'providerRequestId',
      'resolutionReceiptId',
      'frameId'
    ]
  ) {
    if (
      !isNonEmptyString(
        packet002Transfer[field]
      )
    ) {
      issues.push(
        createBridgeIssue(
          'PACKET_002_IDENTITY_MISSING',
          `${field} must be a non-empty string.`,
          {
            field:
              `packet002Transfer.${field}`
          }
        )
      );
    }
  }

  const rawSourceObjectIds =
    packet002Transfer.sourceObjectIds;

  const rawSourceZoneIds =
    packet002Transfer.sourceZoneIds;

  const rawLatticeRegionIds =
    packet002Transfer.latticeRegionIds;

  if (
    presentationMode ===
    H_EARTH_3D_FIRST_ADMITTED_WET_SAND_PROOF_MODE
  ) {
    const firstProofProvenance =
      validateExactFirstProofProvenance({
        sourceObjectIds:
          rawSourceObjectIds,

        sourceZoneIds:
          rawSourceZoneIds,

        latticeRegionIds:
          rawLatticeRegionIds
      });

    issues.push(
      ...firstProofProvenance.issues
    );
  }

  const sourceObjectIds =
    isCanonicalStringArray(
      rawSourceObjectIds
    )
      ? rawSourceObjectIds
      : canonicalUniqueStrings(
          rawSourceObjectIds
        );

  const sourceZoneIds =
    isCanonicalStringArray(
      rawSourceZoneIds
    )
      ? rawSourceZoneIds
      : canonicalUniqueStrings(
          rawSourceZoneIds
        );

  const latticeRegionIds =
    isCanonicalStringArray(
      rawLatticeRegionIds
    )
      ? rawLatticeRegionIds
      : canonicalUniqueStrings(
          rawLatticeRegionIds
        );

  const toleranceContext =
    packet002Transfer
      .toleranceContext;

  if (
    toleranceContext !== null &&
    !isHEarthGeometryToleranceContext(
      toleranceContext
    )
  ) {
    issues.push(
      createBridgeIssue(
        'TOLERANCE_CONTEXT_INVALID',
        'Packet 002 toleranceContext must be null or satisfy the public geometry validator.',
        {
          field:
            'packet002Transfer.toleranceContext'
        }
      )
    );
  }

  const bounds =
    packet002Transfer.bounds;

  const boundsValid =
    toleranceContext === null
      ? isHEarthAABB3D(bounds)
      : isHEarthAABB3D(
          bounds,
          toleranceContext
        );

  if (!boundsValid) {
    issues.push(
      createBridgeIssue(
        'PACKET_002_BOUNDS_INVALID',
        'Packet 002 bounds must satisfy the public AABB validator.',
        {
          field:
            'packet002Transfer.bounds'
        }
      )
    );
  }

  const admittedPrimitives =
    packet002Transfer
      .admittedPrimitives;

  if (
    !Array.isArray(
      admittedPrimitives
    ) ||
    admittedPrimitives.length === 0
  ) {
    issues.push(
      createBridgeIssue(
        'ADMITTED_PRIMITIVES_MISSING',
        'Packet 002 must preserve a non-empty admittedPrimitives array.',
        {
          field:
            'packet002Transfer.admittedPrimitives'
        }
      )
    );
  }

  if (Array.isArray(admittedPrimitives)) {
    admittedPrimitives.forEach(
      (
        primitive,
        index
      ) => {
        if (
          !isHEarthAdmittedPrimitiveRecord(
            primitive
          )
        ) {
          issues.push(
            createBridgeIssue(
              'ADMITTED_PRIMITIVE_INVALID',
              'Every Packet 002 admitted primitive must satisfy the public West validator.',
              {
                field:
                  `packet002Transfer.admittedPrimitives[${index}]`
              }
            )
          );
        }

        if (
          primitive?.aggregateFrameMember !==
          false
        ) {
          issues.push(
            createBridgeIssue(
              'STANDALONE_PRIMITIVE_MEMBERSHIP_FLAG_INVALID',
              'Packet 002 standalone primitives must preserve aggregateFrameMember === false.',
              {
                field:
                  `packet002Transfer.admittedPrimitives[${index}].aggregateFrameMember`,

                expected:
                  false,

                actual:
                  primitive?.aggregateFrameMember ??
                  null
              }
            )
          );
        }
      }
    );
  }

  const standaloneMembership =
    evaluatePrimitiveMembership(
      admittedPrimitives
    );

  if (!standaloneMembership.ok) {
    issues.push(
      createBridgeIssue(
        'ADMITTED_PRIMITIVE_MEMBERSHIP_INVALID',
        'Packet 002 admitted primitive IDs must be present and unique.',
        {
          field:
            'packet002Transfer.admittedPrimitives',

          details:
            standaloneMembership
        }
      )
    );
  }

  const aggregateFrame =
    packet002Transfer
      .aggregateFrameAdmissionRecord;

  if (
    !isHEarthAggregateFrameAdmissionRecord(
      aggregateFrame
    )
  ) {
    issues.push(
      createBridgeIssue(
        'AGGREGATE_FRAME_RECORD_INVALID',
        'Packet 002 aggregateFrameAdmissionRecord must satisfy the public West validator.',
        {
          field:
            'packet002Transfer.aggregateFrameAdmissionRecord'
        }
      )
    );
  }

  const expectedAggregateStatus =
    getAggregateFrameAdmittedStatus();

  if (
    expectedAggregateStatus !== null &&
    aggregateFrame?.status !==
      expectedAggregateStatus
  ) {
    issues.push(
      createBridgeIssue(
        'AGGREGATE_FRAME_STATUS_INVALID',
        'Aggregate-frame status does not match the controlling West admitted status.',
        {
          field:
            'packet002Transfer.aggregateFrameAdmissionRecord.status',

          expected:
            expectedAggregateStatus,

          actual:
            aggregateFrame?.status ??
            null
        }
      )
    );
  }

  if (
    aggregateFrame?.recordType !==
    'H_EARTH_WEST_ADMITTED_AGGREGATE_FRAME_RECORD'
  ) {
    issues.push(
      createBridgeIssue(
        'AGGREGATE_FRAME_RECORD_TYPE_INVALID',
        'Aggregate-frame recordType does not match the West aggregate-frame record type.',
        {
          field:
            'packet002Transfer.aggregateFrameAdmissionRecord.recordType',

          expected:
            'H_EARTH_WEST_ADMITTED_AGGREGATE_FRAME_RECORD',

          actual:
            aggregateFrame?.recordType ??
            null
        }
      )
    );
  }

  if (
    aggregateFrame?.admitted !==
      true ||
    aggregateFrame
      ?.admissionAuthority !==
      'WEST'
  ) {
    issues.push(
      createBridgeIssue(
        'AGGREGATE_FRAME_ADMISSION_AUTHORITY_INVALID',
        'Aggregate-frame admission must remain admitted by West.',
        {
          field:
            'packet002Transfer.aggregateFrameAdmissionRecord'
        }
      )
    );
  }

  const aggregateFrameId =
    normalizeString(
      aggregateFrame?.frameId
    );

  const packetFrameId =
    normalizeString(
      packet002Transfer.frameId
    );

  if (
    aggregateFrameId !==
    packetFrameId
  ) {
    issues.push(
      createBridgeIssue(
        'AGGREGATE_FRAME_ID_MISMATCH',
        'Packet 002 frameId must match aggregateFrameAdmissionRecord.frameId.',
        {
          field:
            'packet002Transfer.frameId',

          expected:
            aggregateFrameId,

          actual:
            packetFrameId
        }
      )
    );
  }

  const aggregatePrimitives =
    aggregateFrame?.primitives;

  if (
    !Array.isArray(
      aggregatePrimitives
    ) ||
    aggregatePrimitives.length === 0
  ) {
    issues.push(
      createBridgeIssue(
        'AGGREGATE_FRAME_PRIMITIVES_MISSING',
        'Aggregate-frame admission must preserve a non-empty primitives array.',
        {
          field:
            'packet002Transfer.aggregateFrameAdmissionRecord.primitives'
        }
      )
    );
  }

  if (Array.isArray(aggregatePrimitives)) {
    aggregatePrimitives.forEach(
      (
        primitive,
        index
      ) => {
        if (
          !isHEarthAdmittedPrimitiveRecord({
            ...primitive,
            aggregateFrameMember: false
          })
        ) {
          issues.push(
            createBridgeIssue(
              'AGGREGATE_FRAME_PRIMITIVE_INVALID',
              'Every aggregate-frame primitive must satisfy the public West validator.',
              {
                field:
                  `packet002Transfer.aggregateFrameAdmissionRecord.primitives[${index}]`
              }
            )
          );
        }

        if (
          primitive?.aggregateFrameMember !==
          true
        ) {
          issues.push(
            createBridgeIssue(
              'AGGREGATE_FRAME_MEMBER_FLAG_INVALID',
              'Aggregate-frame primitives must preserve aggregateFrameMember === true.',
              {
                field:
                  `packet002Transfer.aggregateFrameAdmissionRecord.primitives[${index}].aggregateFrameMember`,

                expected:
                  true,

                actual:
                  primitive?.aggregateFrameMember ??
                  null
              }
            )
          );
        }
      }
    );
  }

  const aggregateMembership =
    evaluatePrimitiveMembership(
      aggregatePrimitives
    );

  if (!aggregateMembership.ok) {
    issues.push(
      createBridgeIssue(
        'AGGREGATE_FRAME_PRIMITIVE_MEMBERSHIP_INVALID',
        'Aggregate-frame primitive IDs must be present and unique.',
        {
          field:
            'packet002Transfer.aggregateFrameAdmissionRecord.primitives',

          details:
            aggregateMembership
        }
      )
    );
  }

  if (
    standaloneMembership.ok &&
    aggregateMembership.ok &&
    !arraysEqual(
      standaloneMembership.primitiveIds,
      aggregateMembership.primitiveIds
    )
  ) {
    issues.push(
      createBridgeIssue(
        'PACKET_002_FRAME_PRIMITIVE_MEMBERSHIP_MISMATCH',
        'Standalone and aggregate-frame primitive membership must match by primitiveId.',
        {
          expected:
            standaloneMembership.primitiveIds,

          actual:
            aggregateMembership.primitiveIds
        }
      )
    );
  }

  if (
    Array.isArray(
      aggregateFrame?.primitiveIds
    )
  ) {
    if (
      !isCanonicalStringArray(
        aggregateFrame.primitiveIds
      ) ||
      !arraysEqual(
        aggregateFrame.primitiveIds,
        standaloneMembership.primitiveIds
      )
    ) {
      issues.push(
        createBridgeIssue(
          'AGGREGATE_FRAME_PRIMITIVE_ID_LIST_MISMATCH',
          'Aggregate-frame primitiveIds must be canonical, duplicate-free, and match admitted primitive membership exactly.',
          {
            field:
              'packet002Transfer.aggregateFrameAdmissionRecord.primitiveIds',

            expected:
              standaloneMembership.primitiveIds,

            actual:
              aggregateFrame.primitiveIds
          }
        )
      );
    }
  }

  if (
    Number.isSafeInteger(
      aggregateFrame?.primitiveCount
    ) &&
    Array.isArray(
      aggregatePrimitives
    ) &&
    aggregateFrame.primitiveCount !==
      aggregatePrimitives.length
  ) {
    issues.push(
      createBridgeIssue(
        'AGGREGATE_FRAME_PRIMITIVE_COUNT_MISMATCH',
        'Aggregate-frame primitiveCount must match aggregate-frame membership.',
        {
          field:
            'packet002Transfer.aggregateFrameAdmissionRecord.primitiveCount',

          expected:
            aggregatePrimitives.length,

          actual:
            aggregateFrame.primitiveCount
        }
      )
    );
  }

  const aggregateBounds =
    aggregateFrame?.bounds;

  const aggregateBoundsValid =
    toleranceContext === null
      ? isHEarthAABB3D(
          aggregateBounds
        )
      : isHEarthAABB3D(
          aggregateBounds,
          toleranceContext
        );

  if (!aggregateBoundsValid) {
    issues.push(
      createBridgeIssue(
        'AGGREGATE_FRAME_BOUNDS_INVALID',
        'Aggregate-frame bounds must satisfy the public AABB validator.',
        {
          field:
            'packet002Transfer.aggregateFrameAdmissionRecord.bounds'
        }
      )
    );
  }

  if (
    presentationMode ===
      H_EARTH_3D_FIRST_ADMITTED_WET_SAND_PROOF_MODE &&
    (
      bounds?.empty !== false ||
      aggregateBounds?.empty !== false
    )
  ) {
    issues.push(
      createBridgeIssue(
        'FIRST_PROOF_EMPTY_BOUNDS_REJECTED',
        'FIRST_ADMITTED_WET_SAND_PROOF requires nonempty Packet 002 and aggregate-frame geometry bounds.',
        {
          expected:
            Object.freeze({
              packet002BoundsEmpty:
                false,

              aggregateFrameBoundsEmpty:
                false
            }),

          actual:
            Object.freeze({
              packet002BoundsEmpty:
                bounds?.empty ??
                null,

              aggregateFrameBoundsEmpty:
                aggregateBounds?.empty ??
                null
            })
        }
      )
    );
  }

  if (
    boundsValid &&
    aggregateBoundsValid &&
    !areAABB3DRecordsEquivalent(
      bounds,
      aggregateBounds,
      toleranceContext,
      0
    )
  ) {
    issues.push(
      createBridgeIssue(
        'PACKET_002_BOUNDS_CORRESPONDENCE_MISMATCH',
        'Packet 002 bounds must correspond exactly to aggregate-frame bounds.',
        {
          field:
            'packet002Transfer.bounds'
        }
      )
    );
  }

  const frameMetadata =
    extractFrameMetadata(
      aggregateFrame
    );

  if (
    !isCanonicalStringArray(
      frameMetadata?.sourceObjectIds
    )
  ) {
    issues.push(
      createBridgeIssue(
        'AGGREGATE_FRAME_SOURCE_OBJECT_ARRAY_NOT_CANONICAL',
        'Aggregate-frame sourceObjectIds must be a canonical duplicate-free string array.',
        {
          field:
            'packet002Transfer.aggregateFrameAdmissionRecord.metadata.sourceObjectIds'
        }
      )
    );
  }

  if (
    !isCanonicalStringArray(
      frameMetadata?.sourceZoneIds
    )
  ) {
    issues.push(
      createBridgeIssue(
        'AGGREGATE_FRAME_SOURCE_ZONE_ARRAY_NOT_CANONICAL',
        'Aggregate-frame sourceZoneIds must be a canonical duplicate-free string array.',
        {
          field:
            'packet002Transfer.aggregateFrameAdmissionRecord.metadata.sourceZoneIds'
        }
      )
    );
  }

  if (
    !isCanonicalStringArray(
      frameMetadata?.latticeRegionIds
    )
  ) {
    issues.push(
      createBridgeIssue(
        'AGGREGATE_FRAME_LATTICE_REGION_ARRAY_NOT_CANONICAL',
        'Aggregate-frame latticeRegionIds must be a canonical duplicate-free string array.',
        {
          field:
            'packet002Transfer.aggregateFrameAdmissionRecord.metadata.latticeRegionIds'
        }
      )
    );
  }

  const frameRequestId =
    normalizeString(
      frameMetadata?.requestId
    );

  const frameProviderRequestId =
    normalizeString(
      frameMetadata?.providerRequestId
    );

  const frameResolutionReceiptId =
    normalizeString(
      frameMetadata?.resolutionReceiptId
    );

  const frameSourceObjectIds =
    isCanonicalStringArray(
      frameMetadata?.sourceObjectIds
    )
      ? frameMetadata.sourceObjectIds
      : canonicalUniqueStrings(
          frameMetadata?.sourceObjectIds
        );

  const frameSourceZoneIds =
    isCanonicalStringArray(
      frameMetadata?.sourceZoneIds
    )
      ? frameMetadata.sourceZoneIds
      : canonicalUniqueStrings(
          frameMetadata?.sourceZoneIds
        );

  const frameLatticeRegionIds =
    isCanonicalStringArray(
      frameMetadata?.latticeRegionIds
    )
      ? frameMetadata.latticeRegionIds
      : canonicalUniqueStrings(
          frameMetadata?.latticeRegionIds
        );

  if (
    frameRequestId !==
    normalizeString(
      packet002Transfer.requestId
    )
  ) {
    issues.push(
      createBridgeIssue(
        'AGGREGATE_FRAME_REQUEST_PROVENANCE_MISMATCH',
        'Aggregate-frame requestId must match Packet 002 requestId.',
        {
          expected:
            packet002Transfer.requestId,

          actual:
            frameRequestId
        }
      )
    );
  }

  if (
    frameProviderRequestId !==
    normalizeString(
      packet002Transfer.providerRequestId
    )
  ) {
    issues.push(
      createBridgeIssue(
        'AGGREGATE_FRAME_PROVIDER_REQUEST_PROVENANCE_MISMATCH',
        'Aggregate-frame providerRequestId must match Packet 002 providerRequestId.',
        {
          expected:
            packet002Transfer.providerRequestId,

          actual:
            frameProviderRequestId
        }
      )
    );
  }

  if (
    frameResolutionReceiptId !==
    normalizeString(
      packet002Transfer.resolutionReceiptId
    )
  ) {
    issues.push(
      createBridgeIssue(
        'AGGREGATE_FRAME_RESOLUTION_RECEIPT_PROVENANCE_MISMATCH',
        'Aggregate-frame resolutionReceiptId must match Packet 002 resolutionReceiptId.',
        {
          expected:
            packet002Transfer.resolutionReceiptId,

          actual:
            frameResolutionReceiptId
        }
      )
    );
  }

  if (
    !arraysEqual(
      frameSourceObjectIds,
      sourceObjectIds
    )
  ) {
    issues.push(
      createBridgeIssue(
        'AGGREGATE_FRAME_SOURCE_OBJECT_PROVENANCE_MISMATCH',
        'Aggregate-frame sourceObjectIds must match Packet 002 sourceObjectIds.',
        {
          expected:
            sourceObjectIds,

          actual:
            frameSourceObjectIds
        }
      )
    );
  }

  if (
    !arraysEqual(
      frameSourceZoneIds,
      sourceZoneIds
    )
  ) {
    issues.push(
      createBridgeIssue(
        'AGGREGATE_FRAME_SOURCE_ZONE_PROVENANCE_MISMATCH',
        'Aggregate-frame sourceZoneIds must match Packet 002 sourceZoneIds.',
        {
          expected:
            sourceZoneIds,

          actual:
            frameSourceZoneIds
        }
      )
    );
  }

  if (
    !arraysEqual(
      frameLatticeRegionIds,
      latticeRegionIds
    )
  ) {
    issues.push(
      createBridgeIssue(
        'AGGREGATE_FRAME_LATTICE_PROVENANCE_MISMATCH',
        'Aggregate-frame latticeRegionIds must match Packet 002 latticeRegionIds.',
        {
          expected:
            latticeRegionIds,

          actual:
            frameLatticeRegionIds
        }
      )
    );
  }

  const standaloneProvenance =
    validatePrimitiveSourceProvenance({
      primitives:
        admittedPrimitives,

      sourceObjectIds,
      sourceZoneIds,
      latticeRegionIds,

      fieldPrefix:
        'packet002Transfer.admittedPrimitives'
    });

  issues.push(
    ...standaloneProvenance.issues
  );

  const aggregateProvenance =
    validatePrimitiveSourceProvenance({
      primitives:
        Array.isArray(aggregatePrimitives)
          ? aggregatePrimitives
          : [],

      sourceObjectIds,
      sourceZoneIds,
      latticeRegionIds,

      fieldPrefix:
        'packet002Transfer.aggregateFrameAdmissionRecord.primitives'
    });

  issues.push(
    ...aggregateProvenance.issues
  );

  return Object.freeze({
    ok:
      issues.length === 0,

    issues:
      freezeIssues(issues),

    requestId:
      normalizeString(
        packet002Transfer.requestId
      ),

    providerRequestId:
      normalizeString(
        packet002Transfer.providerRequestId
      ),

    resolutionReceiptId:
      normalizeString(
        packet002Transfer.resolutionReceiptId
      ),

    sourceObjectIds,
    sourceZoneIds,
    latticeRegionIds,

    admittedPrimitives,

    admittedPrimitiveIds:
      standaloneMembership.primitiveIds,

    aggregateFrameAdmissionRecord:
      aggregateFrame,

    aggregateFrameId:
      packetFrameId,

    bounds,
    toleranceContext
  });
}
